import { useState } from "react";

export function DoubleClick({
  itemLabel = "{{itemLabel}}",
  icon = "{{icon}}",
  triggered: initialTriggered = {{triggered}},
  accent = "{{accent}}",
}) {
  const [triggered, setTriggered] = useState(initialTriggered);
  const icons = { file: "\ud83d\udcc4", folder: "\ud83d\udcc1", image: "\ud83d\uddbc" };
  return (
    <div style={{ width: 300, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <div onDoubleClick={() => setTriggered(true)}
        style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 10px", borderRadius: 8, width: "fit-content", background: triggered ? accent : "transparent" }}>
        <span style={{ fontSize: 20 }}>{icons[icon]}</span><span>{itemLabel}</span>
      </div>
      {triggered && <div style={{ marginTop: 10, padding: 14, borderRadius: 8, background: "#FAF7F2", border: "1.5px solid " + accent, boxShadow: "0 8px 20px rgba(36,20,48,.15)", fontSize: 13 }}>
        <p style={{ margin: 0 }}>Opening {itemLabel}&hellip;</p>
      </div>}
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430aa" }}>{triggered ? "double-click triggered open \u2014 a single click only selects" : "single click selects \u00b7 double-click opens"}</p>
    </div>
  );
}
